function materialCount(k){return Number(s.materials[k]||0)}
function materialRow(){return '<div class="material-grid">'+[['hingeDust','HINGE DUST','Epic'],['mimicShards','MIMIC SHARDS','Rare'],['dragonScales','DRAGON SCALES','Legendary'],['herbs','HERBS','Uncommon']].map(function(m){return '<div class="material-chip"><span class="material-art">'+gameArt(m[0],m[2])+'</span><b>'+materialCount(m[0])+'</b><small>'+m[1]+'</small></div>'}).join('')+'</div>'}
function bag(){var list=s.bag.map(function(id){return get(id)}).filter(Boolean),counts={};list.forEach(function(x){counts[x.id]=(counts[x.id]||0)+1});var unique=Object.keys(counts).map(get).filter(Boolean),shown=unique.filter(function(x){return cat==='all'||x.type===cat}),equippedCount=['weapon','armor','companion'].filter(function(k){return !!get(s.gear[k])}).length;var cards=shown.map(function(x){var rarity=String(x.rarity||'common').toLowerCase().replace(/[^a-z0-9-]/g,''),slot=['weapon','armor','companion'].indexOf(x.type)>=0,active=slot&&s.gear[x.type]===x.id,level=Number(s.upgrades[x.id]||0);return '<button class="loot-card rarity-'+rarity+(active?' is-equipped':'')+'" data-item="'+esc(x.id)+'"><span class="loot-rarity">'+esc(x.rarity||'Common')+'</span><span class="loot-art"><i></i><b>'+gameArt(x.id,x.rarity)+'</b></span><span class="loot-name">'+esc(x.name)+'</span><span class="loot-kind">'+esc(x.type.toUpperCase())+'</span><span class="loot-foot"><small>OWNED ×'+counts[x.id]+'</small>'+(slot&&level?'<small>FORGE +'+level+'</small>':'')+'</span>'+(active?'<span class="loot-equipped">EQUIPPED</span>':'')+'</button>'}).join('');var relicCards=cat==='all'?s.relics.map(function(id){var r=(D.relicCatalog||[]).find(function(x){return x.id===id});if(!r)return '';var rarity=String(r.rarity||'common').toLowerCase();return '<button class="loot-card relic-loot rarity-'+rarity+'" data-relic="'+esc(r.id)+'"><span class="loot-rarity">'+esc(r.rarity||'RELIC')+'</span><span class="loot-art"><i></i><b>'+gameArt(r.id,r.rarity)+'</b></span><span class="loot-name">'+esc(r.name)+'</span><span class="loot-kind">PERMANENT RELIC</span><span class="loot-foot"><small>DISCOVERED</small></span></button>'}).join(''):'';return '<div class="vault-overview"><div class="vault-title"><div><div class="eyebrow">PERSONAL COLLECTION · SECURE STORAGE</div><h2>THE CRAWLER VAULT</h2><p>The things you found. The things you bought. The things that probably should not be glowing.</p></div><div class="vault-chest-mark">♜</div></div><div class="vault-stat-row"><div><b>'+list.length+'</b><small>TOTAL ITEMS</small></div><div><b>'+unique.length+'</b><small>UNIQUE ITEMS</small></div><div><b>'+equippedCount+'/3</b><small>GEAR SLOTS</small></div><div><b>'+s.relics.length+'</b><small>RELICS</small></div></div></div><div class="vault-equipped-strip"><div class="vault-strip-head"><span>ACTIVE LOADOUT</span><button data-fac="armory">OPEN ARMORY ↗</button></div><div class="vault-mini-slots">'+['weapon','armor','companion'].map(function(k){var x=get(s.gear[k]);return '<button data-fac="armory" class="vault-mini-slot"><span>'+(x?gameArt(x.id,x.rarity):'◇')+'</span><small>'+k.toUpperCase()+'</small><b>'+esc(x?x.name:'EMPTY')+'</b></button>'}).join('')+'</div></div><div class="bag-filters vault-filters">'+['all','weapon','armor','companion','potion','title'].map(function(k){return '<button class="pill '+(cat===k?'active':'')+'" data-cat="'+k+'">'+k.toUpperCase()+'</button>'}).join('')+'</div><div class="vault-section-head"><div><div class="eyebrow">YOUR ACQUISITIONS</div><h3>'+ (cat==='all'?'TREASURE COLLECTION':cat.toUpperCase()+' COLLECTION')+'</h3></div><small>'+shown.length+' ITEMS</small></div><div class="loot-grid">'+cards+relicCards+'</div>'+(!shown.length&&!relicCards?'<div class="empty vault-empty">This shelf is empty. The goblins are taking notes.</div>':'')+'<section class="vault-materials"><div class="vault-section-head"><div><div class="eyebrow">CRAFTING COMPONENTS</div><h3>MATERIAL LOCKER</h3></div></div>'+materialRow()+'</section>'}
function recipeCard(id,name,desc,cost,materials){return '<article class="craft-recipe"><div class="recipe-head"><span>🧪</span><div><h3>'+name+'</h3><p>'+desc+'</p></div></div><div class="recipe-cost">◈ '+cost+' coins · '+materials+'</div><button class="action primary" data-craft="'+id+'">CRAFT POTION</button></article>'}
function forge(){return '<div class="facility-intro"><div class="eyebrow">UPGRADE & ASCENSION</div><h2>THE FORGE</h2><p>Make your gear less embarrassing. Upgrades stop at +5; then the item ascends.</p></div>'+['weapon','armor'].map(function(slot){var id=s.gear[slot],it=get(id);return '<article class="forge-slot"><div class="item-icon">'+(it?gameArt(it.id,it.rarity):'⚒️')+'</div><div><h3>'+esc(it?it.name:'No '+slot+' equipped')+'</h3><p>'+ (it?'ASCENSION LEVEL +'+Number(s.upgrades[id]||0):'Equip an item before upgrading')+'</p></div>'+(it?'<button class="action" data-upgrade="'+id+'">UPGRADE · '+(500*(Number(s.upgrades[id]||0)+1)).toLocaleString()+'</button>':'')+'</article>'}).join('')+'<div class="panel"><h3>YOUR MATERIAL STORES</h3>'+materialRow()+'</div>'}
function alchemy(){return '<div class="facility-intro"><div class="eyebrow">BREW SOMETHING QUESTIONABLE</div><h2>ALCHEMY LAB</h2><p>Craft fold-count potions from materials. Activate them from your bag.</p></div>'+materialRow()+recipeCard('liquidgold','Liquid Gold','+25% coins for 25 folds',350,'2 Hinge Dust · 3 Herbs')+recipeCard('experience','Elixir of Experience','+50% XP for 50 folds',550,'2 Hinge Dust · 1 Mimic Shard · 2 Herbs')+recipeCard('fortune',"Fortune's Favor",'+25% rare finds for 40 folds',650,'2 Mimic Shards · 3 Herbs')+recipeCard('dragonbreath',"Dragon's Breath",'+50% XP for 30 folds',900,'2 Dragon Scales · 1 Mimic Shard')+recipeCard('nectar','Companion Nectar','Double companion XP for 50 folds',700,'2 Hinge Dust · 1 Mimic Shard · 4 Herbs')}
function pets(){
var companions=s.bag.map(get).filter(function(x){return x&&x.type==='companion'});
var active=get(s.gear.companion),stage=s.companionLevel>=30?'ANCIENT':s.companionLevel>=20?'ASCENDED':s.companionLevel>=10?'VETERAN':s.companionLevel>=5?'GROWN':'YOUNG';
var next=s.companionLevel>=30?null:s.companionLevel>=20?30:s.companionLevel>=10?20:s.companionLevel>=5?10:5;
var progress=next?Math.max(0,Math.min(100,(s.companionXP%100))):100;
var abilities={goblin:'Scavenger Instinct · +5% coin find',dragon:'Emberheart · +10% experience',cat:'Midnight Prowler · +10% coin find',demon:'Little Calamity · +15% experience'};
var activeAbility=active?(abilities[active.id]||'Dungeon Bond · passive companion bonus'):'No companion bond active';
return '<div class="companion-sanctuary"><div class="eyebrow">PARTY ROSTER · CREATURE BONDING</div><h2>THE COMPANION SANCTUARY</h2><p>They are not pets. They are highly opinionated coworkers with claws.</p></div>'+
(active?'<section class="companion-showcase rarity-'+String(active.rarity||'Common').toLowerCase()+'"><div class="companion-showcase-art">'+gameArt(active.id,active.rarity)+'</div><div class="companion-showcase-info"><div class="eyebrow">ACTIVE PARTY MEMBER · '+esc(active.rarity||'COMMON')+'</div><h3>'+esc(active.name)+'</h3><p>'+esc(active.desc||'A loyal-ish dungeon companion.')+'</p><div class="companion-stage">'+stage+' FORM <span>LEVEL '+s.companionLevel+'</span></div><div class="companion-xp"><div><span>EVOLUTION PROGRESS</span><b>'+(next?'NEXT: LEVEL '+next:'MAX EVOLUTION')+'</b></div><div class="bar"><span style="width:'+progress+'%"></span></div><small>'+s.companionXP+' COMPANION XP · '+(next?Math.max(0,100-(s.companionXP%100))+' XP TO NEXT STAGE':'EVOLUTION COMPLETE')+'</small></div><div class="companion-ability"><span>✧ SIGNATURE TRAIT</span><b>'+esc(activeAbility)+'</b></div><button class="action" data-equip="'+active.id+'">DISMISS FROM PARTY</button></div></section>':
'<section class="companion-showcase companion-empty"><div class="companion-showcase-art">'+gameArt('cat','Rare')+'</div><div><div class="eyebrow">YOUR PARTY IS EMPTY</div><h3>No companion bonded</h3><p>Recruit a creature from the Goblin Exchange. It may or may not respect you.</p><button class="action primary" data-fac="shop">VISIT THE SHOP</button></div></section>')+
'<div class="companion-roster-heading"><div><div class="eyebrow">YOUR COLLECTION</div><h3>AVAILABLE PARTY MEMBERS</h3></div><span>'+companions.length+' / 4 RECRUITED</span></div>'+
(companions.length?'<div class="companion-roster">'+companions.map(function(x){var isActive=active&&active.id===x.id,rarity=String(x.rarity||'Common').toLowerCase();return '<article class="companion-roster-card rarity-'+rarity+(isActive?' is-active':'')+'"><div class="companion-roster-art">'+gameArt(x.id,x.rarity)+'</div><div class="companion-roster-copy"><small>'+esc(x.rarity||'COMMON')+' COMPANION</small><h4>'+esc(x.name)+'</h4><p>'+esc(x.desc||'A strange but potentially useful ally.')+'</p><b>'+(isActive?'IN YOUR PARTY':'AVAILABLE')+'</b></div><div class="companion-roster-actions"><button class="action" data-item="'+x.id+'">INSPECT</button><button class="action '+(isActive?'':'primary')+'" data-equip="'+x.id+'">'+(isActive?'ACTIVE':'JOIN PARTY')+'</button></div></article>'}).join('')+'</div>':'<div class="empty">No companions recruited yet. The shop has several questionable candidates.</div>')+
'<div class="companion-evolution-guide"><div class="eyebrow">EVOLUTION PATH</div><div class="companion-evolution-steps"><span class="'+(s.companionLevel>=1?'reached':'')+'">YOUNG<small>Lv. 1</small></span><i></i><span class="'+(s.companionLevel>=5?'reached':'')+'">GROWN<small>Lv. 5</small></span><i></i><span class="'+(s.companionLevel>=10?'reached':'')+'">VETERAN<small>Lv. 10</small></span><i></i><span class="'+(s.companionLevel>=20?'reached':'')+'">ASCENDED<small>Lv. 20</small></span><i></i><span class="'+(s.companionLevel>=30?'reached':'')+'">ANCIENT<small>Lv. 30</small></span></div><p>Companions gain experience whenever new folds are recorded. Evolution is automatic; your save data and existing thresholds remain unchanged.</p></div>';
}
function relics(){var found=s.relics.length,total=(D.relicCatalog||[]).length;return '<section class="relic-archive-hero"><div class="eyebrow">ANCIENT POWER · PERMANENT DISCOVERIES</div><h2>THE RELIC ARCHIVE</h2><p>Some treasures are older than the dungeon. Some are older than the laws against keeping them.</p><div class="relic-archive-progress"><div><b>'+found+' / '+total+'</b><small>RELICS DISCOVERED</small></div><div class="bar"><span style="width:'+(total?found/total*100:0)+'%"></span></div></div></section><div class="relic-collection-grid">'+(D.relicCatalog||[]).map(function(r,i){var has=s.relics.indexOf(r.id)>=0,rarity=String(r.rarity||'Common').toLowerCase();return '<article class="relic-collection-card rarity-'+rarity+(has?' is-found':' is-hidden')+'"><div class="relic-card-art">'+gameArt(r.id,r.rarity)+'</div><div class="relic-card-copy"><small>'+esc(r.rarity||'RELIC')+' · '+(has?'ARCHIVED':'UNDISCOVERED')+'</small><h3>'+(has?esc(r.name):'UNKNOWN RELIC #'+(i+1))+'</h3><p>'+(has?esc(r.desc):'A lost artifact. Its identity will be revealed when you discover it.')+'</p><div class="relic-bonus-line">'+Object.keys(r.effects||{}).map(function(k){return (k==='xp'?'XP':k==='coins'?'COINS':k.toUpperCase())+' +'+Math.round(r.effects[k]*100)+'%'}).join(' · ')+'</div></div><span class="relic-status">'+(has?'✦':'?')+'</span></article>'}).join('')+'</div>'}
function armory(){var slots=['weapon','armor','companion'],effects=passiveEffects(),relics=s.relics.map(function(id){return (D.relicCatalog||[]).find(function(x){return x.id===id})}).filter(Boolean),weapon=get(s.gear.weapon),armor=get(s.gear.armor),setActive=!!(weapon&&armor&&weapon.set&&weapon.set===armor.set);return '<div class="armory-hero"><div class="armory-hero-copy"><div class="eyebrow">CHARACTER EQUIPMENT · LOADOUT</div><h2>THE WARDEN ARMORY</h2><p>Every piece has a purpose. Even the questionable hat.</p></div><div class="armory-crest">⚔</div><div class="armory-power"><div><b>'+slots.filter(function(k){return !!get(s.gear[k])}).length+'</b><small>GEAR SLOTS FILLED</small></div><div><b>'+relics.length+'</b><small>RELICS BOUND</small></div><div><b>+'+Math.round((effects.coins||0)*100)+'%</b><small>COIN BONUS</small></div><div><b>+'+Math.round((effects.xp||0)*100)+'%</b><small>XP BONUS</small></div></div></div><div class="armory-loadout"><div class="armory-section-title"><div><div class="eyebrow">YOUR ACTIVE BUILD</div><h3>EQUIPPED RELICS & GEAR</h3></div><span>3 SLOTS</span></div>'+slots.map(function(k){var x=get(s.gear[k]),rarity=String(x&&x.rarity||'common').toLowerCase().replace(/[^a-z0-9-]/g,'');return '<article class="armory-item '+(x?'rarity-'+rarity:'is-empty')+'"><div class="armory-slot-label">'+(k==='weapon'?'MAIN HAND':k==='armor'?'BODY ARMOR':'COMPANION')+'</div><div class="armory-item-art"><i></i><b>'+(x?gameArt(x.id,x.rarity):'◇')+'</b></div><div class="armory-item-info"><small>'+(x?esc(x.rarity||'COMMON'):'VACANT SLOT')+'</small><h3>'+esc(x?x.name:'Nothing equipped')+'</h3><p>'+(x&&x.effects?Object.keys(x.effects).map(function(e){return (e==='coins'?'COINS':e==='xp'?'XP':e==='rare'?'RARE FINDS':e.toUpperCase())+' +'+Math.round(x.effects[e]*100)+'%'}).join(' · '):'Choose an item from your crawler vault.')+'</p>'+(x&&(k==='weapon'||k==='armor')?'<div class="armory-upgrade">FORGE ASCENSION <b>+'+Number(s.upgrades[x.id]||0)+' / 5</b></div>':'')+'</div><div class="armory-item-actions">'+(x?'<button class="action" data-item="'+esc(x.id)+'">INSPECT</button><button class="action remove-gear" data-equip="'+esc(x.id)+'">UNEQUIP</button>':'<button class="action primary" data-fac="bag">CHOOSE GEAR</button>')+'</div></article>'}).join('')+(setActive?'<div class="armory-set-bonus"><span>✦ ROYAL SET BONUS ACTIVE</span><b>+10% COINS · +5% XP</b><small>Your weapon and armor share the Royal lineage.</small></div>':'')+'</div><section class="armory-bonus-panel"><div class="armory-section-title"><div><div class="eyebrow">PASSIVE POWER</div><h3>YOUR COMBINED BONUSES</h3></div><span>✧</span></div><div class="armory-bonus-grid">'+[['coins','◈','COIN FIND'],['xp','✦','EXPERIENCE'],['rare','◇','RARE FINDS'],['companionXP','🐾','COMPANION XP']].map(function(k){return '<div><span>'+k[1]+'</span><small>'+k[2]+'</small><b>+'+Math.round((effects[k[0]]||0)*100)+'%</b></div>'}).join('')+'</div><p>Bonuses combine from equipped gear, upgrades, relics and active companions. They apply to newly recorded folds.</p></section><section class="armory-relic-panel"><div class="armory-section-title"><div><div class="eyebrow">PERMANENT COLLECTION</div><h3>BOUND RELICS</h3></div><span>'+relics.length+' FOUND</span></div>'+(relics.length?'<div class="armory-relic-grid">'+relics.map(function(r){return '<button class="armory-relic" data-relic="'+esc(r.id)+'"><span>'+gameArt(r.id,r.rarity)+'</span><div><b>'+esc(r.name)+'</b><small>'+esc(r.rarity)+' · PERMANENT</small></div><i>↗</i></button>'}).join('')+'</div>':'<div class="empty">No relics bound yet. The dungeon has not decided you are worthy. Fair.</div>')+'</section>'}
function rewards(){var all=ach.concat(D.dailyAchievements||[]);return '<div class="facility-intro"><div class="eyebrow">MILESTONES & DAILY LOOT</div><h2>REWARDS HALL</h2><p>Claim each milestone once. Your past folds count; future rewards are waiting.</p></div>'+all.map(function(a,i){var daily=i>=ach.length,done=daily?s.today>=a.at:s.folds>=a.at,key=(daily?'daily-':'life-')+a.at,claimed=s.claimedAchievements.indexOf(key)>=0;return '<article class="reward-row"><div class="item-icon">🏆</div><div><h3>'+esc(a.name)+'</h3><p>'+a.at+(daily?' folds today':' lifetime folds')+' · '+a.coins+' coins · '+a.xp+' XP</p></div><button class="action" '+(!done||claimed?'disabled':'')+' data-reward="'+key+'">'+(claimed?'CLAIMED':done?'CLAIM':'LOCKED')+'</button></article>'}).join('')}
function facilitiesMenu(){var entries=[['bag','CRAWLER VAULT','Store, inspect and organize every hard-won acquisition.','STORAGE','bag'],['shop','GOBLIN EXCHANGE','Trade coins for gear, companions and questionable bargains.','TRADING','shop'],['forge','EMBER FORGE','Strengthen your weapon and armor through five ascensions.','UPGRADES','forge'],['alchemy','VEILED APOTHECARY','Brew fold-count bonuses from the materials you collect.','CRAFTING','alchemy'],['pets','COMPANION SANCTUARY','Recruit, bond with and evolve your dungeon party.','PARTY','pets'],['relics','RELIC ARCHIVE','Discover permanent artifacts and build lasting power.','COLLECTION','relics'],['armory','WARDEN ARMORY','Manage your active equipment and combined bonuses.','LOADOUT','armory'],['rewards','HALL OF TRIUMPH','Claim daily contracts and lifetime milestones.','REWARDS','rewards']];var unlocked=s.relics.length,gear=['weapon','armor','companion'].filter(function(k){return !!get(s.gear[k])}).length;return '<div class="base-of-operations"><section class="base-hero"><div class="base-hero-art">'+gameArt('relics','Legendary')+'</div><div class="eyebrow">CRAWLER HEADQUARTERS · ESTABLISHED BY QUESTIONABLE DECISIONS</div><h1>BASE OF OPERATIONS</h1><p>Eight districts. One increasingly concerning crawler. Everything you need to prepare for the next descent.</p><div class="base-status-strip"><div><b>◈ '+s.coins.toLocaleString()+'</b><small>AVAILABLE COINS</small></div><div><b>'+gear+'/3</b><small>GEAR SLOTS FILLED</small></div><div><b>'+unlocked+'</b><small>RELICS FOUND</small></div><div><b>'+s.bag.length+'</b><small>ITEMS IN VAULT</small></div></div></section><div class="base-section-heading"><div><div class="eyebrow">YOUR HEADQUARTERS</div><h2>CHOOSE A DISTRICT</h2><p>Select a facility to enter and manage its services.</p></div><span>08 DISTRICTS</span></div><div class="base-district-grid">'+entries.map(function(f,i){return '<button class="base-district-card district-'+f[4]+'" data-fac="'+f[0]+'"><div class="district-art">'+gameArt(f[4],['Epic','Rare','Legendary','Epic','Uncommon','Legendary','Rare','Legendary'][i])+'</div><div class="district-card-copy"><small>DISTRICT 0'+(i+1)+' · '+f[3]+'</small><h3>'+f[1]+'</h3><p>'+f[2]+'</p><span>ENTER DISTRICT <b>↗</b></span></div></button>'}).join('')+'</div><section class="base-command-note"><div class="eyebrow">DUNGEON AI · OPERATIONS NOTICE</div><p>“All facilities are operational. Staff morale is questionable. Please stop feeding the forge.”</p></section></div>'}function guild(){var scenes={bag:['THE TREASURE VAULT','Where every questionable acquisition is carefully misfiled.','vault','A treasury of trophies, tools and things that may still be cursed.'],shop:['THE GOBLIN EXCHANGE','Fair prices are not guaranteed. Neither is the goblin.','merchant','A crooked little market where every deal has fine print.'],forge:['THE EMBER FORGE','Steel remembers every hammer blow. So does the blacksmith.','anvil','A furnace-lit workshop built for turning good gear into dangerous gear.'],alchemy:['THE VEILED APOTHECARY','Measured ingredients. Unmeasured consequences.','flask','A hidden laboratory of glass, herbs and volatile possibilities.'],pets:['THE COMPANION SANCTUARY','Loyalty is earned one fold at a time. Treat the staff well.','companion','A quiet refuge for the creatures brave enough to join your party.'],relics:['THE RELIC ARCHIVE','Some treasures are older than the dungeon itself.','archive','An ancient chamber where every artifact has a story and a price.'],armory:['THE WARDEN ARMORY','Your active build. Your very questionable life choices.','warden','A fortified equipment hall for preparing your next descent.'],rewards:['THE HALL OF TRIUMPH','The dungeon keeps score. It is annoyingly thorough.','trophy','A ceremonial hall honoring every milestone you somehow survived.']},v=scenes[facility]||scenes.bag,body=facility==='bag'?bag():facility==='shop'?'<div class="facility-intro"><div class="eyebrow">SPEND WISELY. OR DO NOT.</div><h2>DUNGEON SHOP</h2><p>Equipment, companions, potions, titles and useful mistakes.</p></div>'+shop():facility==='pets'?pets():facility==='forge'?forge():facility==='alchemy'?alchemy():facility==='relics'?relics():facility==='armory'?armory():facility==='rewards'?rewards():bag();return '<div class="facility-scene scene-'+facility+'"><section class="district-environment district-environment-'+facility+'"><div class="district-environment-art">'+gameArt(v[2],facility==='rewards'||facility==='relics'?'Legendary':facility==='pets'?'Uncommon':'Epic')+'</div><div class="district-environment-copy"><div class="eyebrow">DUNGEON DISTRICT · '+facility.toUpperCase()+'</div><h2>'+v[0]+'</h2><p>'+v[1]+'</p><small>'+v[3]+'</small></div><div class="district-environment-lights"></div></section>'+body+'</div>'}function profile(){var gear=['weapon','armor','companion'].map(function(k){var x=get(s.gear[k]);return '<article class="profile-gear"><span>'+(x?gameArt(x.id,x.rarity):'◇')+'</span><div><small>'+k.toUpperCase()+'</small><b>'+esc(x?x.name:'EMPTY SLOT')+'</b><p>'+(x&&x.effects?Object.keys(x.effects).map(function(e){return e+' +'+Math.round(x.effects[e]*100)+'%'}).join(' · '):'No active bonus')+'</p></div>'+(x?'<button class="action" data-equip="'+x.id+'">REMOVE</button>':'<button class="action" data-fac="bag">BAG</button>')+'</article>'}).join('');var potions=s.activePotions.length?s.activePotions.map(function(p){return '<div class="potion-line"><span>🧪</span><div><b>'+esc(p.name)+'</b><small>'+(p.kind==='fold'?p.remainingFolds+' FOLDS REMAINING':p.kind==='timed'?Math.max(0,Math.ceil((p.endsAt-Date.now())/60000))+' MINUTES REMAINING':p.charges+' CHARGES')+'</small></div></div>'}).join(''):'<p class="muted-copy">No active effects. The bottles are feeling neglected.</p>';return '<div class="rpg-page profile-page"><section class="profile-crest"><div class="eyebrow">THE DUNGEON REGISTRY · OFFICIAL CRAWLER RECORD</div><div class="profile-avatar">♙</div><h1>'+esc(s.name||"Unnamed Crawler")+'</h1><p>CRAWLER #'+s.number+' · '+esc(s.title||'UNRANKED ADVENTURER')+'</p><div class="profile-level"><span>LEVEL</span><strong>'+level()+'</strong><span>'+s.xp.toLocaleString()+' TOTAL XP</span></div></section><section class="profile-stat-grid"><div><small>LIFETIME FOLDS</small><b>'+s.folds.toLocaleString()+'</b></div><div><small>EXPERIENCE</small><b>'+s.xp.toLocaleString()+'</b></div><div><small>COIN PURSE</small><b>◈ '+s.coins.toLocaleString()+'</b></div></section><section class="rpg-panel"><div class="rpg-section-head"><div><div class="eyebrow">IDENTITY & REPUTATION</div><h2>YOUR CRAWLER</h2></div><span>✦</span></div><p class="muted-copy">Your name is how the dungeon remembers you. Your number is how it files the paperwork.</p><button class="action primary" data-act="rename">EDIT NAME · '+(s.name?'5,000 COINS':'FREE')+'</button><div class="identity-options"><div><b>RANDOM REASSIGNMENT</b><p>15,000 coins + 10 Hinge Dust + 5 Mimic Shards.</p><button class="action" data-identity="random">REROLL NUMBER</button></div><div><b>CHOOSE YOUR NUMBER</b><p>50,000 coins + 50 Hinge Dust + 25 Mimic Shards + 10 Dragon Scales.</p><button class="action" data-identity="custom">CUSTOM NUMBER</button></div></div></section><section class="rpg-panel"><div class="rpg-section-head"><div><div class="eyebrow">YOUR ACTIVE BUILD</div><h2>WORN & WIELDED</h2></div><span>⚔</span></div>'+gear+'</section><section class="rpg-panel"><div class="rpg-section-head"><div><div class="eyebrow">TEMPORARY POWER</div><h2>ACTIVE POTIONS</h2></div><span>⚗</span></div>'+potions+'</section></div>'}function quests(){var dailyDone=s.today>=5,dailyClaimed=!!s.claimed,progress=Math.min(100,s.today/5*100);return '<div class="rpg-page quests-page"><section class="quest-hero"><div class="eyebrow">THE DUNGEON ALWAYS HAS A TASK</div><h1>CRAWLER CONTRACTS</h1><p>Complete your daily assignment. The dungeon insists this builds character.</p><div class="quest-progress"><div><span>DAILY FOLDS</span><b>'+Math.min(5,s.today)+' / 5</b></div><div class="bar"><span style="width:'+progress+'%"></span></div><small>'+(dailyDone?'Contract complete. Collect your reward.':'A few more folds and the dungeon might stop judging you.')+'</small></div>'+(dailyDone&&!dailyClaimed?'<button class="action primary" data-act="claim">CLAIM 50 COINS + 50 XP</button>':dailyClaimed?'<div class="claimed-mark">✓ DAILY REWARD CLAIMED</div>':'')+'</section><section class="quest-section"><div class="rpg-section-head"><div><div class="eyebrow">LIFETIME MILESTONES</div><h2>THE LONG ROAD</h2></div><span>🏅</span></div><p class="muted-copy">Every fold leaves a mark. These milestones track your lifetime progress.</p>'+ach.slice(0,12).map(function(a){var done=s.folds>=a.at;return '<article class="milestone-row '+(done?'milestone-done':'')+'"><span class="milestone-icon">'+(done?'✓':'◇')+'</span><div><b>'+esc(a.name)+'</b><small>'+a.at.toLocaleString()+' LIFETIME FOLDS · '+a.coins+' COINS · '+a.xp+' XP</small></div><strong>'+(done?'EARNED':'LOCKED')+'</strong></article>'}).join('')+'</section></div>'}function info(){return '<div class="rpg-page info-page"><section class="manual-hero"><div class="manual-sigil">ⓘ</div><div class="eyebrow">FIELD NOTES FOR THE SURVIVING CRAWLER</div><h1>THE DUNGEON CODEX</h1><p>A guide to the rules, rewards, and questionable decisions that keep this operation running.</p></section><section class="rpg-panel manual-section"><div class="rpg-section-head"><div><div class="eyebrow">BEGIN YOUR DESCENT</div><h2>HOW TO PLAY</h2></div><span>⌖</span></div><div class="manual-entry"><b>01 · RECORD YOUR FOLDS</b><p>Record your lifetime fold total to earn coins and XP for newly recorded folds. Safari cannot detect hinge movement by itself.</p></div><div class="manual-entry"><b>02 · BUILD YOUR CRAWLER</b><p>Buy gear in the Shop, equip it from your Bag, and grow through levels and milestones.</p></div><div class="manual-entry"><b>03 · EXPAND YOUR POWER</b><p>Upgrade equipment, craft potions, discover relics, and raise companions as you progress.</p></div></section><section class="rpg-panel manual-section"><div class="rpg-section-head"><div><div class="eyebrow">PROGRESSION & SYNC</div><h2>FOLD TOTAL</h2></div><span>✧</span></div><p class="muted-copy">Have a current lifetime fold count? Enter it here to update your crawler rewards. Only enter a total that is equal to or higher than your saved total.</p><button class="action primary" data-act="sync">ENTER TOTAL MANUALLY</button><p class="sync-status">'+(s.lastSyncAt?'Last updated: '+esc(new Date(s.lastSyncAt).toLocaleString()):'No manual fold total has been entered yet.')+'</p></section><section class="rpg-panel manual-section"><div class="rpg-section-head"><div><div class="eyebrow">PROTECT YOUR PROGRESS</div><h2>SAVE DATA</h2></div><span>▣</span></div><p class="muted-copy">Your progress is stored locally for guests and in your private account when signed in. Export a backup before clearing Safari data.</p><button class="action" data-act="export">EXPORT SAVE BACKUP</button><button class="action danger-action" data-act="reset">RESET CHARACTER</button></section><p class="codex-footer">THE DUNGEON REMEMBERS. MAKE IT WORTH ITS WHILE.</p></div>'}function render(){if(!root)return;document.getElementById("coins").textContent=s.coins.toLocaleString();document.getElementById("dust").textContent=s.dust;if(page==="home")root.innerHTML=home();else if(page==="facilities")root.innerHTML=facilitiesMenu();else if(page==="facility")root.innerHTML='<div class="facility-heading"><button class="link" data-page="home">← HOME</button><div class="eyebrow">DUNGEON FACILITY</div><h1>'+esc((facs.find(function(x){return x[0]===facility})||["","FACILITY"])[1]) +'</h1></div><section class="facility-content">'+guild()+'</section>';else if(page==="profile")root.innerHTML=profile();else if(page==="quests")root.innerHTML=quests();else root.innerHTML=info();document.querySelectorAll("[data-page]").forEach(function(b){b.classList.toggle("active",b.dataset.page===page)});save()}
function itemComment(x){return (D.itemAIComments||{})[x.id]||((x.type==='weapon'?'The dungeon has approved this blade. The dungeon approves very little.':x.type==='armor'?'Protects your body from danger and your reputation from absolutely nothing.':x.type==='companion'?'Your new associate has questionable references and excellent potential.':x.type==='potion'?'A suspicious liquid with measurable benefits. Do not ask about the color.':'A curious acquisition. The AI has filed it under “your problem.”'))}
function showItem(id){var x=get(id);if(!x)return;var body=document.getElementById('detail-body'),count=s.bag.filter(function(v){return v===id}).length,equipped=s.gear[x.type]===id,rarity=String(x.rarity||'Common').toLowerCase().replace(/[^a-z0-9-]/g,''),upgrade=Number(s.upgrades[id]||0),effects=x.effects||(x.potion&&x.potion.effect)||{},effectNames={coins:'COIN FIND',xp:'EXPERIENCE',rare:'RARE FINDS',companionXP:'COMPANION XP',achievement:'ACHIEVEMENT REWARD'};var effectMarkup=Object.keys(effects).length?'<section class="inspect-effects"><div class="inspect-kicker">ITEM ATTRIBUTES</div><div class="inspect-effect-grid">'+Object.keys(effects).map(function(k){var v=Number(effects[k]||0);return '<div><small>'+esc(effectNames[k]||k.toUpperCase())+'</small><b>'+(v>0?'+':'')+Math.round(v*100)+'%</b></div>'}).join('')+'</div></section>':'';var potion=x.potion?'<div class="inspect-meta-line"><span>BREW TYPE</span><b>'+esc(x.potion.kind==='timed'?'Timed effect':x.potion.kind==='achievement'?'One-time reward charge':'Fold-count effect')+'</b></div><div class="inspect-meta-line"><span>DURATION</span><b>'+esc(x.potion.kind==='timed'?Number(x.potion.minutes||0)+' minutes':x.potion.kind==='achievement'?Number(x.potion.charges||1)+' charge(s)':Number(x.potion.folds||0)+' folds')+'</b></div>':'';var status=count?'<span class="inspect-owned">OWNED ×'+count+'</span>':'<span class="inspect-unowned">NOT YET ACQUIRED</span>';body.innerHTML='<div class="item-inspection rarity-'+rarity+'"><div class="inspect-topline"><span class="inspect-rarity">'+esc(x.rarity||'Common')+'</span><span class="inspect-type">'+esc(x.type.toUpperCase())+'</span></div><div class="inspect-art"><div class="inspect-art-glow"></div><span>'+gameArt(x.id,x.rarity)+'</span><small>✦ DUNGEON ARCHIVE ✦</small></div><div class="inspect-heading"><div class="eyebrow">ITEM IDENTIFICATION</div><h2>'+esc(x.name)+'</h2><p>'+esc(x.desc||'A mysterious dungeon object.')+'</p></div><blockquote class="inspect-narrator"><span>THE DUNGEON AI SAYS</span>'+esc(itemComment(x))+'</blockquote>'+effectMarkup+'<section class="inspect-details"><div class="inspect-meta-line"><span>COLLECTION STATUS</span>'+status+'</div>'+(x.type==='weapon'||x.type==='armor'?'<div class="inspect-meta-line"><span>FORGE ASCENSION</span><b>+'+upgrade+' / 5</b></div>':'')+(equipped?'<div class="inspect-equipped">✦ CURRENTLY EQUIPPED</div>':'')+potion+'</section><div class="inspect-actions">'+(x.type==='potion'&&count?'<button class="action primary" data-use="'+esc(id)+'">DRINK POTION</button>':(['weapon','armor','companion'].indexOf(x.type)>=0&&count?'<button class="action primary" data-equip="'+esc(id)+'">'+(equipped?'UNEQUIP ITEM':'EQUIP ITEM')+'</button>':''))+(!count&&x.price!=null?'<button class="action primary" data-buy="'+esc(id)+'">ACQUIRE · ◈ '+Number(x.price).toLocaleString()+'</button>':'')+'<button class="action" data-close>RETURN TO INVENTORY</button></div></div>';document.getElementById('detail').showModal()}
function buy(id){var x=get(id);if(!x)return;if(x.type==='identity'){toast('Identity licenses are available in the identity counter update.');return}if(s.coins<Number(x.price||0)){toast('Not enough coins, crawler.');return}if(x.type==='companion'&&s.bag.indexOf(id)>=0){toast('You already own this companion.');return}s.coins-=Number(x.price||0);s.bag.push(id);document.getElementById('detail').close();render();toast('ACQUIRED: '+x.name)}
function equip(id){var x=get(id);if(!x||s.bag.indexOf(id)<0)return;if(['weapon','armor','companion'].indexOf(x.type)<0){toast('This item cannot be equipped');return}s.gear[x.type]=s.gear[x.type]===id?null:id;document.getElementById('detail').close();render();toast(s.gear[x.type]?'EQUIPPED: '+x.name:'UNEQUIPPED')}
function usePotion(id){var x=get(id);if(!x||x.type!=='potion')return;var ix=s.bag.indexOf(id);if(ix<0){toast('Potion not found in your bag.');return}var p=x.potion||{},entry={id:id,name:x.name,kind:p.kind||'fold',effect:p.effect||{},activatedAt:Date.now()};if(p.kind==='timed'){entry.endsAt=Date.now()+Number(p.minutes||10)*60000;s.activePotions.push(entry)}else if(p.kind==='achievement'){entry.charges=Number(p.charges||1);s.activePotions.push(entry)}else{entry.remainingFolds=Number(p.folds||25);s.activePotions.push(entry)}s.bag.splice(ix,1);document.getElementById('detail').close();save();render();toast('POTION ACTIVATED: '+x.name)}
function craft(id){var recipes={liquidgold:{cost:350,hingeDust:2,herbs:3},experience:{cost:550,hingeDust:2,mimicShards:1,herbs:2},fortune:{cost:650,mimicShards:2,herbs:3},dragonbreath:{cost:900,dragonScales:2,mimicShards:1},nectar:{cost:700,hingeDust:2,mimicShards:1,herbs:4}},r=recipes[id],x=get(id);if(!r||!x)return;var keys=['hingeDust','mimicShards','dragonScales','herbs'];if(s.coins<r.cost||keys.some(function(k){return materialCount(k)<(r[k]||0)})){toast('Missing coins or crafting materials.');return}s.coins-=r.cost;keys.forEach(function(k){s.materials[k]=materialCount(k)-(r[k]||0)});s.bag.push(id);save();render();toast('CRAFTED: '+x.name)}
function upgrade(id){var x=get(id),n=Number(s.upgrades[id]||0),cost=500*(n+1);if(!x||n>=5){toast('Maximum upgrade reached.');return}if(s.coins<cost){toast('You need '+cost+' coins.');return}s.coins-=cost;s.upgrades[id]=n+1;save();render();toast(x.name+' upgraded to +'+(n+1))}
function claimReward(key){var parts=key.split('-'),daily=parts[0]==='daily',at=Number(parts[1]),pool=daily?(D.dailyAchievements||[]):ach,a=pool.find(function(x){return x.at===at});if(!a||s.claimedAchievements.indexOf(key)>=0||(daily?s.today:s.folds)<at){toast('That reward is not ready.');return}s.claimedAchievements.push(key);s.coins+=a.coins;s.xp+=a.xp;var boost=s.activePotions.find(function(p){return p.kind==='achievement'&&p.charges>0});if(boost){s.coins+=a.coins;s.xp+=a.xp;boost.charges--;s.activePotions=s.activePotions.filter(function(p){return p.charges!==0})}save();render();toast('REWARD CLAIMED: +'+a.coins+' coins · +'+a.xp+' XP')}
function showRelic(id){var r=(D.relicCatalog||[]).find(function(x){return x.id===id});if(!r)return;document.getElementById('detail-body').innerHTML='<div class="item-icon">'+r.emoji+'</div><h2>'+esc(r.name)+'</h2><p>'+esc(r.desc)+'</p><p>PERMANENT RELIC · DISCOVERED</p>';document.getElementById('detail').showModal()}
function passiveEffects(){var out={coins:0,xp:0,rare:0,companionXP:0};["weapon","armor","companion"].forEach(function(slot){var x=get(s.gear[slot]);if(x&&x.effects)Object.keys(x.effects).forEach(function(k){out[k]=(out[k]||0)+Number(x.effects[k]||0)})});(D.relicCatalog||[]).forEach(function(r){if(s.relics.indexOf(r.id)>=0)Object.keys(r.effects||{}).forEach(function(k){out[k]=(out[k]||0)+Number(r.effects[k]||0)})});["weapon","armor"].forEach(function(slot){var id=s.gear[slot],lvl=Number(s.upgrades[id]||0),x=get(id);if(x&&lvl){var key=x.effects&&x.effects.xp&&!x.effects.coins?"xp":"coins";out[key]+=lvl*.02;if(lvl>=5)out.rare+=.05}});var w=get(s.gear.weapon),a=get(s.gear.armor);if(w&&a&&w.set&&w.set===a.set){out.coins+=.10;out.xp+=.05}var companion=get(s.gear.companion);if(companion){var lv=Math.floor(Math.sqrt(Math.max(0,s.companionXP)/25))+1;out.companionXP+=Math.min(.20,Math.max(0,lv-1)*.002);if(companion.id==="cat")out.rare+=.02;if(companion.id==="demon")out.xp+=.03}return out}
function activeEffects(){var out={coins:0,xp:0,rare:0,companionXP:0},now=Date.now();s.activePotions=s.activePotions.filter(function(p){return p.kind==="fold"?p.remainingFolds>0:p.kind==="achievement"?p.charges>0:p.endsAt>now});s.activePotions.forEach(function(p){Object.keys(p.effect||{}).forEach(function(k){out[k]=(out[k]||0)+Number(p.effect[k]||0)})});return out}
function applyFoldTotal(n,source){if(!Number.isSafeInteger(n)||n<0||n<s.folds){toast("That fold total is invalid or older than this save.");return false}var diff=n-s.folds;if(!diff){s.lastSyncAt=new Date().toISOString();save();render();toast("Already up to date. No duplicate rewards.");return true}var passive=passiveEffects(),active=activeEffects(),gainedCoins=0,gainedXP=0;for(var i=0;i<diff;i++){var effects={};Object.keys(passive).forEach(function(k){effects[k]=(passive[k]||0)+(active[k]||0)});gainedCoins+=Math.floor(2*(1+effects.coins));gainedXP+=Math.floor(10*(1+effects.xp));if(Math.random()<Math.min(.75,effects.rare||0))s.materials.mimicShards++;if(s.gear.companion)s.companionXP+=Math.max(1,Math.round(1+(effects.companionXP||0)));if(Math.random()<.02){s.materials.hingeDust++;s.dust++}if(Math.random()<Math.min(.25,.08+(s.gear.companion==="goblin"?.03:0)))s.materials.herbs++;if(s.gear.companion==="dragon"&&Math.random()<.015)s.materials.dragonScales++;if((s.folds+i+1)%25===0)s.materials.mimicShards++;if((s.folds+i+1)%50===0)s.materials.dragonScales++;if(Math.random()<.0002){var available=(D.relicCatalog||[]).filter(function(r){return s.relics.indexOf(r.id)<0});if(available.length){var roll=Math.random()*100,tier=roll<55?"Common":roll<82?"Rare":roll<96?"Epic":"Legendary",pool=available.filter(function(r){return r.rarity===tier}),choices=pool.length?pool:available,r=choices[Math.floor(Math.random()*choices.length)];s.relics.push(r.id);toast("RELIC DISCOVERED: "+r.name)}}s.activePotions.forEach(function(p){if(p.kind==="fold")p.remainingFolds--})}s.folds=n;s.today+=diff;s.coins+=diff*2+gainedCoins;s.xp+=diff*10+gainedXP;s.lastSyncAt=new Date().toISOString();save();render();toast(diff+" new folds · +"+(diff*2+gainedCoins)+" coins · +"+(diff*10+gainedXP)+" XP");return true}
function syncCloud(){var status=document.querySelector(".sync-status");if(status)status.textContent="Checking cloud fold total…";fetch("https://cbndsdcotvnfkhfjrxst.supabase.co/functions/v1/duo-sync",{method:"GET",headers:{ "Accept":"application/json" },cache:"no-store"}).then(function(r){if(!r.ok)throw new Error("Cloud sync returned HTTP "+r.status);return r.json()}).then(function(data){if(!data||data.ok!==true||!Number.isSafeInteger(Number(data.total))||Number(data.total)<0)throw new Error("Cloud returned an invalid fold total.");var total=Number(data.total);if(total>s.folds){applyFoldTotal(total,"cloud")}else{s.lastCloudSyncAt=new Date().toISOString();save();render()}var el=document.querySelector(".sync-status");if(el)el.textContent="Cloud synced · "+s.folds.toLocaleString()+" lifetime folds · "+new Date(s.lastCloudSyncAt||new Date().toISOString()).toLocaleString()}).catch(function(err){var el=document.querySelector(".sync-status");if(el)el.textContent="Cloud sync unavailable: "+(err&&err.message?err.message:"Unknown error")})}
function sync(){var v=prompt("Enter your lifetime fold total from DuoLog:",String(s.folds));if(v===null)return;var n=Number(v);if(!Number.isSafeInteger(n)){toast("Enter a whole-number lifetime fold total.");return}applyFoldTotal(n,"manual")}
function exportSave(){var blob=new Blob([JSON.stringify({format:"duo-dungeon-save-v2",state:s},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="DuoDungeon-Save.json";a.click();URL.revokeObjectURL(url)}
document.addEventListener("click",function(e){if(e.target.closest("#account-button")){if(AUTH&&AUTH.open)AUTH.open();return}var bonus=e.target.closest("[data-bonus]");if(bonus){showBonus(bonus.dataset.bonus);return}var p=e.target.closest("[data-page]");if(p){page=p.dataset.page;facility="";render();return}var f=e.target.closest("[data-fac]");if(f){page="facility";facility=f.dataset.fac;cat=f.dataset.fac==="pets"?"companion":"all";render();return}var a=e.target.closest("[data-act]");if(a){var act=a.dataset.act;if(act==="sync")sync();else if(act==="rename"){var fee=s.name?5000:0;if(fee&&s.coins<fee){toast("A name change costs 5,000 coins.");return}var n=prompt(fee?"Choose a new crawler name · 5,000 coins:":"Choose your crawler name (first assignment is free):",s.name);if(n!==null&&n.trim()){if(fee)s.coins-=fee;s.name=n.trim().slice(0,20);render();toast(fee?"Identity updated. 5,000 coins spent.":"Your name is now official.")}}else if(act==="export")exportSave();else if(act==="reset"){if(confirm("Erase this browser character and start fresh?")){s=fresh();render()}}else if(act==="claim"&&s.today>=5&&!s.claimed){s.claimed=true;s.coins+=50;s.xp+=50;render();toast("Daily reward claimed")}return}var ident=e.target.closest("[data-identity]");if(ident){var mode=ident.dataset.identity,need=mode==="random"?{hingeDust:10,mimicShards:5}:{hingeDust:50,mimicShards:25,dragonScales:10},price=mode==="random"?15000:50000;if(s.coins<price||Object.keys(need).some(function(k){return materialCount(k)<need[k]})){toast("Identity change requires "+price+" coins and the listed materials.");return}var number;if(mode==="random"){number=100000+Math.floor(Math.random()*900000);if(number===s.number)number=number===999999?100000:number+1}else{var val=prompt("Choose a six-digit crawler number (100000–999999):",String(s.number));if(val===null)return;if(String(val).length!==6||!Number.isInteger(Number(val))||Number(val)<100000||Number(val)>999999||Number(val)===s.number){toast("Enter a different six-digit number.");return}number=Number(val)}if(!confirm("Change your crawler number to #"+number+" for "+price.toLocaleString()+" coins and the required materials?"))return;s.coins-=price;Object.keys(need).forEach(function(k){s.materials[k]=materialCount(k)-need[k]});s.number=number;save();render();toast("CRAWLER NUMBER UPDATED: #"+number);return}var c=e.target.closest("[data-cat]");if(c){cat=c.dataset.cat;render();return}var cr=e.target.closest("[data-craft]");if(cr){craft(cr.dataset.craft);return}var up=e.target.closest("[data-upgrade]");if(up){upgrade(up.dataset.upgrade);return}var rw=e.target.closest("[data-reward]");if(rw){claimReward(rw.dataset.reward);return}var use=e.target.closest("[data-use]");if(use){usePotion(use.dataset.use);return}var relic=e.target.closest("[data-relic]");if(relic){showRelic(relic.dataset.relic);return}var b=e.target.closest("[data-buy]");if(b){buy(b.dataset.buy);return}var it=e.target.closest("[data-item]");if(it){showItem(it.dataset.item);return}var eq=e.target.closest("[data-equip]");if(eq){equip(eq.dataset.equip);return}if(e.target.matches("[data-close]"))document.getElementById("detail").close()});
